package com.bananalab.lite;
import android.content.*;import java.util.*;import org.json.*;
/** Natural, bounded goal orchestration. Every clause is planned before executing any. */
final class ImprovementFlow{
 static final class Step{final String kind,raw;Step(String k,String r){kind=k;raw=r;}}
 static List<Step> plan(String input){String q=NaturalCoding.normalize(input);List<Step> out=new ArrayList<>();
  if(q.startsWith("no ")||q.matches("^(como|por que|que pasa|si|cuando) .*"))return out;
  if(q.matches("(?:que podes mejorar|que falta mejorar|que mas podes cambiar|hasta donde podes cambiar la app|que podes reconstruir)")){out.add(new Step("scope",input));return out;}
  if(q.matches("(?:como van|mostrame|mostra|ver|revisa) (?:las mejoras|el entrenamiento|los entrenamientos|los pesos)(?: de banana)?")){out.add(new Step("status",input));return out;}
  // Quotes may contain conjunctions or words about training: leave those to the reply parser.
  if(input.matches("(?s).*[\"“”].*"))return out;
  String normalized=NaturalCoding.polite(input).replaceAll("(?iu)chat y (?:banana )?pixel\\b","ambos modelos");
  String[] clauses=normalized.split("(?iu)\\s*(?:;|\\by despues\\b|\\by luego\\b|\\by tambien\\b|\\by\\b)\\s*",-1);
  boolean relevant=false;for(String clause:clauses){String n=NaturalCoding.normalize(clause);String kind="";if(n.matches("(?:mejora|mejores|mejorar|entrena|entrenes|entrenar|reentrena|reentrenar) (?:banana )?chat (?:mas a fondo|a fondo|en profundidad|completo)")){out.add(new Step("chatDeep",clause));relevant=true;continue;}if(n.matches("(?:mejora|mejores|mejorar|entrena|entrenes|entrenar|reentrena|reentrenes|reentrenar) (?:banana )?pixel (?:mas a fondo|a fondo|en profundidad)(?: con la referencia actual)?")){out.add(new Step("pixelDeep",clause));relevant=true;continue;}
   if(n.matches("(?:mejora|mejores|mejorar|entrena|entrenes|entrenar|reentrena|reentrenes|reentrenar|ajusta|ajustes) (?:los pesos de |el modelo de |el modelo |la ia de )?(?:banana )?(?:chat|pixel|chat y pixel|chat y banana pixel|ambos modelos)(?: con (?:mis ejemplos|los ejemplos guardados|la referencia actual))?")){boolean both=n.contains(" y ")||n.contains("ambos");kind=both?"both":n.matches(".*\\bpixel(?: con .*)?$")?"pixel":"chat";relevant=true;}
   else if(n.matches("(?:volvamos|volve|volvamos a|vuelve|recupera|restaura) (?:a )?(?:los )?(?:pesos|modelo|modelos) anteriores(?: de | del )?(?:banana )?(chat|pixel)")){kind=n.endsWith("pixel")?"undoPixel":"undoChat";relevant=true;}
   else if(n.matches("(?:actualiza|actualices|actualizar|reconstrui|reconstruye|reconstruyas|reconstruir|prepara|prepares) (?:toda )?(?:la app|banana|la apk)(?: con (?:todo|estos cambios|las mejoras|los pesos nuevos))?|(?:deja|dejes) (?:todo|las mejoras|los cambios) (?:incorporado|incorporados|incorporadas|dentro) (?:en |de )?(?:la app|banana|la apk)")){kind="build";relevant=true;}
   else {try{NaturalCoding.Plan p=NaturalCoding.parse(clause,"");if(p.kind.equals("settings"))kind="settings";else if(p.kind.equals("build")){kind="build";relevant=true;}}catch(IllegalArgumentException unsupported){/* Other bounded program routes may understand this clause. */} }
   out.add(new Step(kind,clause));
  }
  if(!relevant)return new ArrayList<>();if(out.size()>8)throw new IllegalArgumentException("Puedo coordinar hasta ocho partes por pedido.");Set<String> seen=new HashSet<>();boolean built=false;for(Step s:out){if(s.kind.isEmpty())throw new IllegalArgumentException("No entendí esta parte completa: «"+s.raw+"». No inicié ninguna parte del pedido.");if(built)throw new IllegalArgumentException("La actualización debe ir al final del pedido para incluir todos los cambios.");if(s.kind.equals("build"))built=true;if(s.kind.equals("both")){if(!seen.add("chat")||!seen.add("pixel"))throw new IllegalArgumentException("Pediste entrenar el mismo modelo más de una vez.");}else if(s.kind.equals("chat")||s.kind.equals("pixel")||s.kind.equals("pixelDeep")||s.kind.equals("chatDeep")){if(!seen.add(s.kind.equals("pixelDeep")?"pixel":s.kind.equals("chatDeep")?"chat":s.kind))throw new IllegalArgumentException("Pediste entrenar el mismo modelo más de una vez.");}}
  return out;
 }
 static String scope(){return "Podés hablarme normalmente y juntar varias mejoras en un pedido. Por ejemplo: ‘Agranda la letra y mejora los pesos de chat y pixel y actualiza la app con todo’.\nPuedo ajustar interfaz, respuestas y programas Java de listas o texto de hasta12 pasos; entrenar las capas de salida de mis modelos propios y reconstruir todo el Java actual en una APK normal.\nLo que falta para cambios libres mayores es un generador Java general con análisis de dependencias, pruebas de cada función y manejo de recursos y bibliotecas. Recompilar todo no significa que ya sepa diseñar cualquier modificación. Pixel también admite entrenar las cuatro capas de su modelo principal de personajes si pedís mejorarlo más a fondo. El entrenamiento actual es pequeño y no me vuelve automáticamente una IA general.";}
 static BananaEngine.Result handle(Context c,String input)throws Exception{List<Step> steps;try{steps=plan(input);}catch(IllegalArgumentException e){return MobileCore.say(c,e.getMessage(),"app_ajuste");}if(steps.isEmpty())return null;List<Step> expanded=new ArrayList<>();for(Step s:steps){if(s.kind.equals("both")){expanded.add(new Step("chat",s.raw));expanded.add(new Step("pixel",s.raw));}else expanded.add(s);}steps=expanded;StringBuilder receipt=new StringBuilder();String resultTopic="app_ajuste";JavaChat.owner=Thread.currentThread();try{for(int i=0;i<steps.size();i++){Step s=steps.get(i);JavaChat.phase("Mejora "+(i+1)+" de "+steps.size()+": "+s.kind);String text;
   if(s.kind.equals("scope"))text=scope();else if(s.kind.equals("status"))text="Chat: "+NeuralTraining.summary(c,"chat")+"\nPixel: "+NeuralTraining.summary(c,"pixel")+"\nÚltimo pedido: "+prefs(c).getString("receipt","sin cambios coordinados");
   else if(s.kind.equals("chatDeep"))text=DeepChatTraining.train(c);else if(s.kind.equals("chat"))text=NeuralTraining.trainChat(c);else if(s.kind.equals("pixelDeep"))text=NeuralTraining.trainPixel(c,true);else if(s.kind.equals("pixel"))text=NeuralTraining.trainPixel(c);
   else if(s.kind.equals("both")){text=NeuralTraining.trainChat(c)+"\n\n"+NeuralTraining.trainPixel(c);}
   else if(s.kind.startsWith("undo"))text=ModelDepot.undo(c,s.kind.equals("undoChat")?"chat":"pixel");
   else if(s.kind.equals("settings")){NaturalCoding.Plan p=NaturalCoding.parse(s.raw,"");AppJavaWorkspace.restore(c);AppJavaChat.Plan settings=AppJavaChat.plan(p.command,AppJavaWorkspace.live);if(!settings.handled)throw new IllegalArgumentException("No pude preparar el ajuste completo.");AppJavaWorkspace.prepare(c,settings.settings,settings.summary);text=AppJavaWorkspace.apply(c);NaturalCoding.save(c,p,text);}
   else{NaturalCoding.project(c);BananaEngine.Result built=DurableCode.handle(c,"reconstruye mi apk");if(built==null)throw new IllegalStateException("El constructor no devolvió un resultado.");text=built.text;if(!"code_export_apk".equals(built.mode))throw new IllegalStateException(text);resultTopic=built.mode;}
   receipt.append(i+1).append(". ").append(text).append("\n\n");prefs(c).edit().putString("receipt",receipt.toString()).putInt("completed",i+1).commit();
  }return MobileCore.say(c,receipt.toString(),resultTopic);
 }catch(Exception e){return MobileCore.say(c,receipt+"Se detuvo el resto del pedido: "+AndroidRepair.summary(e)+"\nLas partes ya completadas se conservan; no es una transacción global.","app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-improvement-flow",0);}
}
